// Shared helpers for WebsiteBench Harbor OpenCLI adapters.
//
// Generated by `websitebench-harbor opencli-adapters`. Do not hand-edit; edit
// the generator at src/websitebench/harbor/opencli/adapters.py instead.
//
// These adapters drive a LOCAL offline clone over plain HTTP. They never touch
// a browser, so they run without the OpenCLI Chrome Bridge extension. Only
// @jackwener/opencli and Node built-ins may be imported.

import { ArgumentError, CommandExecutionError } from '@jackwener/opencli/errors';

const LOOPBACK_HOSTS = new Set(['127.0.0.1', 'localhost']);

/** Parse and normalize the base URL, refusing every non-loopback target. */
function loopbackBase(base) {
  if (typeof base !== 'string' || !base.trim()) {
    throw new ArgumentError('--base must be a non-empty URL');
  }
  let parsed;
  try {
    parsed = new URL(base);
  } catch (err) {
    throw new ArgumentError(`--base must be a valid URL: ${err.message}`);
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new ArgumentError(`--base must use http or https, got ${parsed.protocol}`);
  }
  if (!LOOPBACK_HOSTS.has(parsed.hostname.toLowerCase())) {
    throw new ArgumentError(`--base must target loopback, got ${parsed.hostname}`);
  }
  if (parsed.username || parsed.password) {
    throw new ArgumentError('--base must not contain credentials');
  }
  if (parsed.search || parsed.hash) {
    throw new ArgumentError('--base must not contain a query or fragment');
  }
  return parsed.href.replace(/\/+$/, '');
}

/** Join a contract-relative route onto a base URL. */
export function resolveRoute(base, route) {
  if (typeof route !== 'string' || route.length === 0) {
    throw new ArgumentError('route must be a non-empty string');
  }
  if (
    route !== route.trim() ||
    route.includes('\\') ||
    /^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(route) ||
    route.startsWith('//')
  ) {
    throw new ArgumentError(`route must be relative, got ${route}`);
  }
  const trimmedBase = loopbackBase(base);
  return `${trimmedBase}/${route.replace(/^\/+/, '')}`;
}

/** Parse the --expect argument, a JSON object of contract required_state. */
export function parseExpect(raw) {
  if (!raw) return {};
  let value;
  try {
    value = JSON.parse(raw);
  } catch (err) {
    throw new ArgumentError(`--expect must be JSON: ${err.message}`);
  }
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw new ArgumentError('--expect must be a JSON object');
  }
  return value;
}

/** Issue one request. Redirects are never followed: the status is evidence. */
export async function request(url, { method = 'GET', session = '', body = null, timeout = 15, referer = '' } = {}) {
  const headers = { Accept: 'text/html,application/xhtml+xml' };
  if (session) headers.Cookie = session;
  if (body !== null) headers['Content-Type'] = 'application/x-www-form-urlencoded';
  // A form POST from a real browser carries Origin/Referer, and clones check
  // them for CSRF. We only ever send the page the form was actually fetched
  // from, so this emulates the browser rather than bypassing the check.
  if (referer) {
    headers.Referer = referer;
    try {
      headers.Origin = new URL(referer).origin;
    } catch {
      /* a malformed referer simply means no Origin header */
    }
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), Math.max(1, timeout) * 1000);
  let response;
  try {
    response = await fetch(url, { method, headers, body, redirect: 'manual', signal: controller.signal });
  } catch (err) {
    throw new CommandExecutionError(`request failed: ${url}`, err.message);
  } finally {
    clearTimeout(timer);
  }
  const text = await response.text();
  return {
    url,
    status: response.status,
    contentType: response.headers.get('content-type') || '',
    location: response.headers.get('location') || '',
    setCookie: cookiePairs(response.headers.getSetCookie?.() ?? []),
    body: text,
  };
}

/** Reduce Set-Cookie headers to a `name=value; name=value` Cookie header. */
function cookiePairs(values) {
  return values
    .map((item) => item.split(';', 1)[0].trim())
    .filter((item) => item.includes('='))
    .join('; ');
}

/** Merge an existing Cookie header with newly issued pairs; later wins. */
export function mergeCookies(existing, issued) {
  const jar = new Map();
  for (const source of [existing, issued]) {
    if (!source) continue;
    for (const pair of source.split(';')) {
      const index = pair.indexOf('=');
      if (index > 0) jar.set(pair.slice(0, index).trim(), pair.slice(index + 1).trim());
    }
  }
  return [...jar].map(([name, value]) => `${name}=${value}`).join('; ');
}

// ---------------------------------------------------------------------------
// Deliberately restricted selector support.
//
// Offline clones are server-rendered, so a full CSS engine is not needed and a
// third-party parser is not permitted. This matcher handles the compound forms
// contracts actually use and throws ArgumentError on anything else, so an
// unsupported selector is a loud failure rather than a silent mismatch.
//
// Supported (the RIGHTMOST compound of a descendant chain is matched):
//   tag            .class          tag.class       #id        tag#id
//   [attr="v"]     tag[attr="v"]   tag[attr*="v"]  tag[attr^="v"]
// ---------------------------------------------------------------------------

const COMPOUND = /^([a-zA-Z][\w-]*)?(#[\w-]+)?((?:\.[\w-]+)*)((?:\[[^\]]+\])*)$/;
const ATTRIBUTE = /\[([\w:-]+)([~^*$|]?=)?"?([^"\]]*)"?\]/g;

export function parseSelector(selector) {
  if (typeof selector !== 'string' || !selector.trim()) {
    throw new ArgumentError('selector must be a non-empty string');
  }
  const compound = selector.trim().split(/\s+(?![^[]*\])/).pop();
  const match = COMPOUND.exec(compound);
  if (!match) {
    throw new ArgumentError(`unsupported selector syntax: ${selector}`);
  }
  const [, tag, id, classes, attributes] = match;
  const parsed = { tag: tag || null, id: id ? id.slice(1) : null, classes: [], attributes: [] };
  if (classes) parsed.classes = classes.split('.').filter(Boolean);
  if (attributes) {
    for (const item of attributes.matchAll(ATTRIBUTE)) {
      parsed.attributes.push({ name: item[1], operator: item[2] || null, value: item[3] });
    }
  }
  if (!parsed.tag && !parsed.id && !parsed.classes.length && !parsed.attributes.length) {
    throw new ArgumentError(`unsupported selector syntax: ${selector}`);
  }
  return parsed;
}

const TAG = /<([a-zA-Z][\w-]*)((?:"[^"]*"|'[^']*'|[^>"'])*)>/g;

function attributesOf(raw) {
  const found = {};
  for (const item of raw.matchAll(/([\w:-]+)\s*=\s*"([^"]*)"/g)) found[item[1]] = item[2];
  for (const item of raw.matchAll(/([\w:-]+)\s*=\s*'([^']*)'/g)) found[item[1]] = item[2];
  return found;
}

function attributeMatches(rule, actual) {
  if (actual === undefined) return false;
  if (!rule.operator) return true;
  if (rule.operator === '=') return actual === rule.value;
  if (rule.operator === '*=') return actual.includes(rule.value);
  if (rule.operator === '^=') return actual.startsWith(rule.value);
  if (rule.operator === '$=') return actual.endsWith(rule.value);
  if (rule.operator === '~=') return actual.split(/\s+/).includes(rule.value);
  throw new ArgumentError(`unsupported attribute operator: ${rule.operator}`);
}

/** Return every match as {tag, attributes, start, end}, document order. */
export function findAll(body, selector) {
  const parsed = parseSelector(selector);
  const matches = [];
  for (const item of body.matchAll(TAG)) {
    const tag = item[1].toLowerCase();
    if (parsed.tag && parsed.tag.toLowerCase() !== tag) continue;
    const attributes = attributesOf(item[2] || '');
    if (parsed.id && attributes.id !== parsed.id) continue;
    const classList = (attributes.class || '').split(/\s+/).filter(Boolean);
    if (!parsed.classes.every((name) => classList.includes(name))) continue;
    if (!parsed.attributes.every((rule) => attributeMatches(rule, attributes[rule.name]))) continue;
    matches.push({ tag, attributes, start: item.index, end: item.index + item[0].length });
  }
  return matches;
}

/** Drop <script>/<style> bodies: they carry code, never rendered evidence. */
export function withoutCode(body) {
  return body.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ');
}

/** Strip tags and collapse whitespace, for visible-text assertions. */
export function visibleText(body) {
  return withoutCode(body)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

export function documentTitle(body) {
  const match = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(body);
  return match ? visibleText(match[1]) : '';
}

/** Find the <form> enclosing `offset`, or the form starting at it. */
export function enclosingForm(body, offset) {
  const opens = [...body.matchAll(/<form\b((?:"[^"]*"|'[^']*'|[^>"'])*)>/gi)];
  for (let index = opens.length - 1; index >= 0; index -= 1) {
    const open = opens[index];
    if (open.index > offset) continue;
    const bodyStart = open.index + open[0].length;
    const closeAt = body.toLowerCase().indexOf('</form>', bodyStart);
    const end = closeAt === -1 ? body.length : closeAt;
    if (offset <= end) {
      return { attributes: attributesOf(open[1] || ''), inner: body.slice(bodyStart, end) };
    }
  }
  return null;
}

/** Serialize a form's controls into an application/x-www-form-urlencoded body. */
export function serializeForm(form) {
  const params = new URLSearchParams();
  for (const item of form.inner.matchAll(/<input\b((?:"[^"]*"|'[^']*'|[^>"'])*)>/gi)) {
    const attributes = attributesOf(item[1] || '');
    if (!attributes.name) continue;
    const type = (attributes.type || 'text').toLowerCase();
    if (type === 'submit' || type === 'button' || type === 'reset' || type === 'file') continue;
    if ((type === 'checkbox' || type === 'radio') && !('checked' in attributes)) continue;
    params.append(attributes.name, attributes.value ?? '');
  }
  for (const item of form.inner.matchAll(/<select\b((?:"[^"]*"|'[^']*'|[^>"'])*)>([\s\S]*?)<\/select>/gi)) {
    const attributes = attributesOf(item[1] || '');
    if (!attributes.name) continue;
    const options = [...item[2].matchAll(/<option\b((?:"[^"]*"|'[^']*'|[^>"'])*)>([\s\S]*?)<\/option>/gi)];
    const chosen = options.find((option) => 'selected' in attributesOf(option[1] || '')) || options[0];
    if (!chosen) continue;
    const chosenAttributes = attributesOf(chosen[1] || '');
    params.append(attributes.name, chosenAttributes.value ?? visibleText(chosen[2]));
  }
  for (const item of form.inner.matchAll(/<textarea\b((?:"[^"]*"|'[^']*'|[^>"'])*)>([\s\S]*?)<\/textarea>/gi)) {
    const attributes = attributesOf(item[1] || '');
    if (attributes.name) params.append(attributes.name, visibleText(item[2]));
  }
  return params.toString();
}

// Contract `required_state` mixes two kinds of entry, and conflating them is
// how a diagnostic starts lying. Assertable keys carry a machine-checkable
// value. Descriptive keys carry author prose ("favorite-button becomes Remove
// favorite") that no substring check can honestly evaluate: asserting them
// yields false failures, and quietly passing them yields false confidence.
// Descriptive entries are therefore recorded with asserted=false and never
// affect a step outcome. The runner counts them so they stay visible.
const ASSERTABLE = new Set([
  'title',
  'visible',
  'list_contains',
  'link_text',
  'favorite_absent',
  'text_absent',
  'animal_id',
  'body_contains',
  'required_fields',
]);

/** Evaluate one contract required_state entry against an observed page. */
export function evaluate(key, expected, page) {
  if (!ASSERTABLE.has(key)) {
    return { observed: '', passed: null, asserted: false };
  }
  const text = visibleText(page.body);
  const contains = (needle) => text.includes(needle);
  switch (key) {
    case 'title': {
      const title = documentTitle(page.body);
      return { observed: title, passed: title.includes(expected), asserted: true };
    }
    case 'favorite_absent':
    case 'text_absent':
      return { observed: contains(expected) ? expected : '', passed: !contains(expected), asserted: true };
    case 'animal_id': {
      // Identifiers live in attributes and the route, which visibleText strips.
      const present = page.body.includes(expected) || (page.url || '').includes(expected);
      return { observed: present ? expected : '', passed: present, asserted: true };
    }
    case 'body_contains': {
      // Asset filenames, data-* values and other markup-level evidence never
      // survive visibleText. Matching raw markup is more brittle than matching
      // rendered text, so prefer `visible` and reach for this only when the
      // expectation genuinely lives in an attribute or a tag.
      const markup = withoutCode(page.body);
      const present = markup.includes(expected);
      return { observed: present ? expected : '', passed: present, asserted: true };
    }
    case 'required_fields': {
      const names = expected.split(',').map((item) => item.trim()).filter(Boolean);
      const missing = names.filter((name) => !new RegExp(`name=["']${name}["']`).test(page.body));
      return {
        observed: missing.length ? `missing: ${missing.join(',')}` : expected,
        passed: missing.length === 0,
        asserted: true,
      };
    }
    default:
      return { observed: contains(expected) ? expected : '', passed: contains(expected), asserted: true };
  }
}

/** Build the fixed-width rows every adapter returns. */
export function observationRows(base, page, expect) {
  const entries = Object.entries(expect);
  if (!entries.length) {
    return [{ ...base, checkKey: '', expected: '', observed: '', passed: true, asserted: false }];
  }
  return entries.map(([key, expected]) => {
    const { observed, passed, asserted } = evaluate(key, String(expected), page);
    return { ...base, checkKey: key, expected: String(expected), observed, passed, asserted };
  });
}
